import "@fontsource/lobster/latin-400.css";
import "@fontsource/pacifico/latin-400.css";
import "@fontsource/dancing-script/latin-400.css";
import "@fontsource/dancing-script/latin-700.css";
import "@fontsource/caveat/latin-400.css";
import "@fontsource/caveat/latin-700.css";
import "@fontsource/source-code-pro/latin-400.css";
import "@fontsource/source-code-pro/latin-700.css";

/** Tibetan fonts included with the app. */
export const BUNDLED_TIBETAN_FONTS = ["Noto Serif Tibetan", "Jomolhari", "Uchen"];
/** English (Latin) fonts included with the app. */
export const BUNDLED_LATIN_FONTS = ["Inter", "Roboto", "Open Sans", "Montserrat", "Lato", "Poppins", "Noto Sans", "Noto Serif", "Merriweather", "Playfair Display", "Oswald", "Raleway", "Bebas Neue", "Lobster", "Pacifico", "Dancing Script", "Caveat", "Source Code Pro"];
export const BUNDLED_FONTS = [...BUNDLED_TIBETAN_FONTS, ...BUNDLED_LATIN_FONTS];

/** Load every bundled font now, so text is drawn in the right face the first time. */
export async function preloadBundledFonts(): Promise<void> {
  await Promise.all(
    BUNDLED_FONTS.flatMap((f) => ["400", "700"].map((w) => document.fonts.load(`${w} 48px "${f}"`, BUNDLED_TIBETAN_FONTS.includes(f) ? "བོད་ཡིག Aa" : "Aa").catch(() => []))),
  );
}
